import '@awesome.me/webawesome/dist/components/button/button.js';
import '@awesome.me/webawesome/dist/components/badge/badge.js';
import '@awesome.me/webawesome/dist/components/progress-bar/progress-bar.js';
import '@awesome.me/webawesome/dist/components/input/input.js';

// Pure, local illustration: no Home Assistant client, network operations or charger actions.
const card = (title, eyebrow, content, cls = '') => `<section class="panel ${cls}"><header class="panel-head"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2></div><span class="sample-tag">SAMPLE</span></header>${content}</section>`;
const badge = (text, variant = 'neutral') => `<wa-badge variant="${variant}" pill>${text}</wa-badge>`;
const metric = (label, value, note) => `<div class="metric"><div class="muted">${label}</div><strong>${value}</strong><div class="muted">${note}</div></div>`;
const bars = [34,42,38,55,67,72,60,46,32,26,20,15,19,25,36,44,54,65,73,61,46,37,31,25].map((height, i) => `<span class="bar ${i >= 8 && i <= 12 ? 'selected' : ''}" style="height:${height}%"></span>`).join('');

document.querySelector('#app').innerHTML = `
<div class="shell"><header class="masthead"><div><div class="brand">SPOTNAV <span>ENHANCED</span></div><h1>Charging, in focus.</h1><p>A single view of your vehicle, plan and charger.</p></div><div class="sample-banner">DESIGN PROTOTYPE · SAMPLE DATA<br><span>Offline illustration — no charger connection</span></div></header>
<div class="dashboard">
${card('Your vehicle', 'OVERVIEW', `<div class="vehicle-top"><div><div class="status-line"><span class="dot"></span> Connected · waiting to charge</div><div class="soc">48<span>%</span></div><p class="muted">Battery level · sample</p></div><div class="target">Target <strong>80%</strong><span>Minimum 40% by 07:00</span></div></div><wa-progress-bar value="48" aria-label="Sample battery level 48 percent"></wa-progress-bar><div class="metrics">${metric('Measured power','0.0 <small>kW</small>','Sample measurement')}${metric('Next planned start','22:00','Proposal, not a guarantee')}${metric('Charging time','2h 45m','Estimated active time')}${metric('Ready in','9h 30m','Elapsed time · estimate')}</div>`, 'overview')}
${card('Prices & plan', 'TONIGHT’S OUTLOOK', `<div class="chart-intro"><div><strong>Lower prices, smarter timing</strong><p>Illustrative price bars and selected proposal · not live data</p></div>${badge('Sample · today', 'brand')}</div><div class="chart" role="img" aria-label="Illustrative sample price bars, with a proposed window highlighted"><div class="cap">Sample soft cap</div><div class="bars">${bars}</div></div><div class="axis"><span>18:00</span><span>22:00</span><span>02:00</span><span>06:00</span></div><div class="tracks"><div><b>Proposal</b><span>22:00–00:45 · calculated, not sent</span></div><div><b>Sent ACK</b><span>Accepted · response only</span></div><div><b>Effective readback</b><span>Mismatch · limits differ from sent</span></div><div><b>Measured charging</b><span>Unknown · no sample history</span></div></div><div class="warning"><strong>Mismatch needs attention</strong><span>Sample readback differs from the sent schedule. An ACK or readback does not prove physical charging.</span></div>`, 'prices')}
${card('Plan controls', 'SIMULATED SETTINGS', `<p class="subtext">Illustrative inputs only. Editing has no effect on a plan or charger.</p><div class="fields"><wa-input label="Target SOC (%)" value="80" type="number"></wa-input><wa-input label="Minimum SOC (%)" value="40" type="number"></wa-input><wa-input label="Soft cap (€/kWh)" value="0.10" type="number" step="0.01"></wa-input><wa-input label="Ready by" value="07:00" type="time"></wa-input></div><div class="hint">Sample basis: variable energy price. Above-cap energy would only be proposed for the minimum SOC.</div><wa-button variant="brand" disabled>Save plan · unavailable</wa-button>`, 'controls')}
${card('Morek status', 'EXECUTION EVIDENCE', `<div class="status-row"><span>Autonomous dispatch</span>${badge('Unarmed', 'warning')}</div><div class="status-row"><span>Proposal</span>${badge('Calculated', 'brand')}</div><div class="status-row"><span>Sent ACK</span>${badge('Accepted', 'success')}</div><div class="status-row"><span>Effective readback</span>${badge('Mismatch', 'danger')}</div><div class="status-row"><span>Measured flow</span>${badge('Unavailable', 'neutral')}</div><p class="subtext">All states are examples. Effective limits are not an inventory of stored profiles.</p><div class="actions"><wa-button size="small" disabled>Send · unavailable</wa-button><wa-button size="small" disabled>Refresh · unavailable</wa-button></div>`, 'morek')}
${card('Recent charging', 'MEASURED HISTORY', `<div class="empty"><div class="empty-symbol">—</div><div><strong>No sample measurements</strong><p>History unavailable in this example. A planned window is not measured charging; missing data is not zero.</p></div></div><div class="footnote">Future view: measured sessions with provenance and gaps.</div>`, 'history')}
${card('Costs & savings', 'ILLUSTRATIVE ESTIMATE', `<div class="costs">${metric('Plan cost','€3.24','Estimated · sample')}${metric('Plan energy','18.0 kWh','Estimated · sample')}</div><div class="divider"></div><div class="status-row"><span>Historical savings</span><strong>Unavailable</strong></div><p class="subtext">A comparable baseline and measured energy are needed; no savings are assumed.</p>`, 'costs-card')}
</div><footer>Sample dashboard only · No live data, commands or Home Assistant access · Visual design awaiting approval</footer></div>`;
